function mascaraCNPJ(v:string){const d=String(v||'').replace(/\D/g,'').slice(0,14);return d.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2')}
function iconeEpi(nome:any){const n=String(nome||'').toLowerCase();if(n.includes('capacete'))return'🪖';if(n.includes('luva'))return'🧤';if(n.includes('bota')||n.includes('calçado')||n.includes('botina'))return'👢';if(n.includes('óculos')||n.includes('oculos')||n.includes('viseira'))return'👓';if(n.includes('máscara')||n.includes('mascara')||n.includes('respirador'))return'😷';if(n.includes('protetor'))return'🎧';if(n.includes('colete')||n.includes('cinto'))return'🦺';if(n.includes('avental'))return'🥼';if(n.includes('perneira'))return'🦵';if(n.includes('creme'))return'🧴';return'🦺'}
function gerarPIN(){return String(Math.floor(1000+Math.random()*9000))}
function gerarSenha(){return 'Previx'+Math.floor(1000+Math.random()*9000)+'@'}
function limparData(v:any){if(!v)return'';v=String(v).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m=v.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');if(v.includes('T'))return v.split('T')[0];return''}
function fmtData(v:any){const l=limparData(v);if(!l)return'-';return l.split('-').reverse().join('/')}
function comparaData(a:any,b:any){return limparData(a.data).localeCompare(limparData(b.data))}
function statusExame(item:any){const d=limparData(item?.data);const res=String(item?.resultado||'').toLowerCase();if(res==='apto'||res==='inapto')return'realizado';if(!d)return'sem-data';const hoje=new Date().toISOString().split('T')[0];if(d===hoje)return'hoje';if(d<hoje)return'vencido';return'futuro'}
function statusDoc(item:any){const v=limparData(item?.vencimento);if(!v)return{label:'Sem vencimento',cor:'#64748b',bg:'#f1f5f9',emoji:'⚪'};const hoje=new Date();hoje.setHours(0,0,0,0);const venc=new Date(v+'T00:00:00');const diff=Math.ceil((venc.getTime()-hoje.getTime())/(1000*60*60*24));if(diff<0)return{label:'VENCIDO',cor:'#fff',bg:'#dc2626',emoji:'🔴'};if(diff<=30)return{label:'A VENCER - '+diff+' dias',cor:'#78350f',bg:'#fef3c7',emoji:'🟡'};return{label:'EM DIA',cor:'#fff',bg:'#16a34a',emoji:'🟢'}}
function statusExtintor(item:any){const v=limparData(item?.vencimento);if(!v)return{label:'Sem data',cor:'#e2e8f0',txt:'#475569',bg:'#f1f5f9',emoji:'⚪'};const hoje=new Date();hoje.setHours(0,0,0,0);const venc=new Date(v+'T00:00:00');const diff=Math.ceil((venc.getTime()-hoje.getTime())/(1000*60*60*24));if(diff<0)return{label:'VENCIDO',cor:'#dc2626',txt:'#fff',bg:'#fee2e2',emoji:'🔴'};if(diff<=30)return{label:'A VENCER - '+diff+' dias',cor:'#f59e0b',txt:'#78350f',bg:'#fef3c7',emoji:'🟡'};return{label:'EM DIA - '+diff+' dias',cor:'#16a34a',txt:'#fff',bg:'#dcfce7',emoji:'🟢'}}
function iconeArquivo(nome:string){const n=String(nome||'').toLowerCase();if(n.endsWith('.pdf'))return'📕';if(n.endsWith('.doc')||n.endsWith('.docx'))return'📘';if(n.endsWith('.xls')||n.endsWith('.xlsx'))return'📗';if(n.endsWith('.jpg')||n.endsWith('.jpeg')||n.endsWith('.png')||n.endsWith('.webp'))return'🖼️';return'📄'}
