function exportarCSV(){const funcs=dadosFiltrados(dados.funcionarios||[]);let csv='nome;cpf;cargo;setor;empresa;telefone;pin\n';funcs.forEach((f:any)=>{csv+=(f.nome||'')+';'+(f.cpf||'')+';'+(f.cargo||'')+';'+(f.setor||'')+';'+(f.empresa||'')+';'+(f.telefone||'')+';'+(f.pin||'')+'\n'});const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='previx-export.csv';a.click()}
function gerarLaudo(tipo:string){const riscos=dadosFiltrados(dados.riscos||[]);const funcs=dadosFiltrados(dados.funcionarios||[]);const empObj=(dados.empresas||[]).find((e:any)=>e.nome===usuario?.empresa)||(dados.empresas||[]).find((e:any)=>e.nome===tecnico.empresaLaudo)||{};const empNome=usuario?.empresa&&usuario.empresa!=='Todas'?usuario.empresa:tecnico.empresaLaudo||empObj.nome||'Empresa';const cnpjFinal=empObj.cnpj||tecnico.cnpj||'A preencher';const hoje=new Date().toLocaleDateString('pt-BR');const validade=new Date(new Date().setFullYear(new Date().getFullYear()+1)).toLocaleDateString('pt-BR');const num='PREVIX-'+new Date().getFullYear()+'-'+String(Math.floor(Math.random()*9000)+1000);const isPGR=tipo.includes('PGR');const isLTCAT=tipo.includes('LTCAT');const isLIP=tipo.includes('LIP');const titulo=isPGR?'PGR - Programa de Gerenciamento de Riscos':isLTCAT?'LTCAT - Laudo Técnico das Condições Ambientais do Trabalho':isLIP?'LIP - Laudo de Insalubridade e Periculosidade':tipo;const sub=isPGR?'NR-01 • NR-09 • NR-17':isLTCAT?'Lei 8.213/91 • NR-15 • NR-16':isLIP?'NR-15 • NR-16':'NR-07 • PCMSO';let linhasR='';if(riscos.length===0)linhasR='<tr><td colspan="8" style="text-align:center;padding:20px">Nenhum risco.</td></tr>';else riscos.forEach((r:any,i:number)=>{linhasR+='<tr><td>'+(i+1)+'</td><td><b>'+(r.ghe||'-')+'</b></td><td>'+(r.nome||'-')+'</td><td>'+(r.tipo||'-')+'</td><td>'+(r.agente||'-')+'</td><td>'+(r.limite||'-')+'</td><td>'+(r.epi||'-')+'</td><td>Monitorar</td></tr>'});let linhasF='';if(funcs.length===0)linhasF='<tr><td colspan="4" style="text-align:center">Nenhum funcionário</td></tr>';else funcs.slice(0,12).forEach((f:any)=>{linhasF+='<tr><td>'+(f.nome||'-')+'</td><td>'+(f.cargo||'-')+'</td><td>'+(f.setor||'-')+'</td><td>'+(f.cpf||'-')+'</td></tr>'});const html='<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+titulo+'</title><style>body{font-family:Arial,sans-serif;color:#0f172a;margin:0;padding:28px;font-size:13px;line-height:1.55}.topo{display:flex;justify-content:space-between;border-bottom:3px solid #0d9488;padding-bottom:14px}.logo{font-size:28px;font-weight:900}.logo span{color:#0d9488}h1{font-size:22px;text-align:center}h2{font-size:14px;background:#0f172a;color:#fff;padding:8px 12px;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:12px}th{background:#0d9488;color:#fff;padding:8px;text-align:left}td{padding:7px;border-bottom:1px solid #e2e8f0}.card{border:1px solid #e2e8f0;border-radius:10px;padding:12px;background:#f8fafc}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.btnprint{text-align:center;margin:18px 0}.btnprint button{background:#0d9488;color:#fff;border:none;padding:13px 26px;border-radius:20px;font-weight:800}@media print{.btnprint{display:none}}</style></head><body>'+'<div class="topo"><div><div class="logo">PREVIX <span>SST</span></div><div>PREVENÇÃO QUE PROTEGE</div></div><div style="text-align:right"><b>'+num+'</b><div>Emitido: '+hoje+'</div><div>Validade: '+validade+'</div></div></div>'+'<h1>'+titulo+'</h1><div style="text-align:center;color:#0d9488;font-weight:800">'+sub+'</div>'+'<div class="grid"><div class="card"><h3>Empresa</h3><p><b>Razão Social:</b> '+empNome+'</p><p><b>CNPJ:</b> '+cnpjFinal+'</p></div>'+'<div class="card"><h3>Responsável Técnico</h3><p><b>Nome:</b> '+(tecnico.nome||'-')+'</p><p><b>Formação:</b> '+(tecnico.formacao||'-')+'</p><p><b>CREA:</b> '+(tecnico.crea||'-')+' • <b>CRM:</b> '+(tecnico.crm||'-')+' • <b>ART:</b> '+(tecnico.art||'-')+'</p></div></div>'+'<h2>INVENTÁRIO</h2><table><thead><tr><th>#</th><th>GHE</th><th>Risco</th><th>Tipo</th><th>Agente</th><th>Limite</th><th>EPI</th><th>Ação</th></tr></thead><tbody>'+linhasR+'</tbody></table>'+'<h2>FUNCIONÁRIOS</h2><table><thead><tr><th>Nome</th><th>Cargo</th><th>Setor</th><th>CPF</th></tr></thead><tbody>'+linhasF+'</tbody></table>'+'<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:40px;text-align:center"><div><div style="border-top:1px solid #000;width:90%;margin:0 auto"></div><b>'+(tecnico.nome||'-')+'</b><div>'+(tecnico.formacao||'')+' • CREA: '+(tecnico.crea||'-')+' • ART: '+(tecnico.art||'-')+'</div></div><div><div style="border-top:1px solid #000;width:90%;margin:0 auto"></div><b>'+(empObj.responsavel||empNome)+'</b><div>CNPJ: '+cnpjFinal+' - '+hoje+'</div></div></div>'+'<div class="btnprint"><button onclick="window.print()">Imprimir / PDF</button></div></body></html>';const w=window.open('','_blank');if(w){w.document.write(html);w.document.close()}}
function gerarRelatorioExtintores(){const exts=dadosFiltrados(dados.extintores||[]);const empObj=(dados.empresas||[]).find((e:any)=>e.nome===usuario?.empresa)||{};const empNome=usuario?.empresa&&usuario.empresa!=='Todas'?usuario.empresa:tecnico.empresaLaudo||empObj.nome||'Empresa';const cnpjFinal=empObj.cnpj||tecnico.cnpj||'A preencher';const hoje=new Date().toLocaleDateString('pt-BR');const qVenc=exts.filter((e:any)=>statusExtintor(e).label.includes('VENCIDO')).length;const qAvencer=exts.filter((e:any)=>statusExtintor(e).label.includes('A VENCER')).length;const qDia=exts.filter((e:any)=>statusExtintor(e).label.includes('EM DIA')).length;let linhas='';if(exts.length===0)linhas='<tr><td colspan="6" style="text-align:center;padding:20px">Nenhum extintor.</td></tr>';else exts.forEach((e:any,i:number)=>{const st=statusExtintor(e);linhas+='<tr><td>'+(i+1)+'</td><td><b>'+(e.localizacao||e.nome||'Extintor')+'</b><div style="font-size:11px;color:#64748b">'+(e.tipo||'-')+'</div></td><td>'+fmtData(e.vencimento)+'</td><td>'+fmtData(e.ultima_recarga)+'</td><td>'+st.emoji+' '+st.label+'</td><td>'+(e.foto?'<img src="'+e.foto+'" style="width:90px;height:90px;object-fit:cover;border-radius:10px" />':'Sem foto')+'</td></tr>'});const html='<html><head><meta charset="utf-8"><title>Relatório Extintores</title><style>body{font-family:Arial;padding:28px;max-width:1000px;margin:0 auto}table{width:100%;border-collapse:collapse}th{background:#dc2626;color:#fff;padding:10px;text-align:left}td{padding:10px;border-bottom:1px solid #e2e8f0}.card{border:1px solid #e2e8f0;border-radius:12px;padding:14px;background:#f8fafc}.btnprint{text-align:center;margin:16px}@media print{.btnprint{display:none}}</style></head><body><h1 style="text-align:center">🧯 Relatório de Extintores - Fiscalização</h1><p style="text-align:center">PREVIX SST • '+hoje+'</p><div class="card"><p><b>Empresa:</b> '+empNome+' • <b>CNPJ:</b> '+cnpjFinal+'</p><p><b>Responsável Técnico:</b> '+tecnico.nome+' • CREA: '+(tecnico.crea||'-')+' • ART: '+(tecnico.art||'-')+'</p><p><b>Resumo:</b> Total: '+exts.length+' • 🔴 Vencido: '+qVenc+' • 🟡 A Vencer: '+qAvencer+' • 🟢 Em Dia: '+qDia+'</p></div><table><thead><tr><th>#</th><th>Localização / Tipo</th><th>Vencimento</th><th>Recarga</th><th>Status</th><th>Foto</th></tr></thead><tbody>'+linhas+'</tbody></table><div class="btnprint"><button onclick="window.print()" style="background:#dc2626;color:#fff;border:none;padding:14px 28px;border-radius:20px;font-weight:800">Imprimir / PDF Fiscalização</button></div></body></html>';const w=window.open('','_blank');if(w){w.document.write(html);w.document.close()}}
function gerarRelatorioInspecao(item:any){const empObj=(dados.empresas||[]).find((e:any)=>e.nome===(item.empresa||usuario?.empresa))||{};const empNome=item.empresa||usuario?.empresa||tecnico.empresaLaudo||empObj.nome||'Empresa';const cnpjFinal=item.cnpjEmpresa||empObj.cnpj||tecnico.cnpj||'A preencher';const enderecoFinal=item.enderecoEmpresa||empObj.endereco||tecnico.enderecoEmpresa||'A preencher';const hoje=new Date().toLocaleDateString('pt-BR');const dataVisita=fmtData(item.data);const tipo=item.tipoInspecao||item.tipo||'Visita Técnica Geral';const motivo=item.motivo||'Rotina Periódica';const metodologias=item.metodologias&&item.metodologias.length?item.metodologias.join(', '):'Visita in loco, Checklist, Fotografias, Consulta às NRs';const checklist=item.checklist||[];let linhasCheck='';if(!checklist.length)linhasCheck='<tr><td colspan="3" style="text-align:center">Nenhum item coletado.</td></tr>';else checklist.forEach((c:any,i:number)=>{const cor=c.status==='Conforme'?'#dcfce7':c.status==='Não Conforme'?'#fee2e2':'#f1f5f9';const icone=c.status==='Conforme'?'✅':c.status==='Não Conforme'?'❌':'⚪';linhasCheck+='<tr><td>'+(i+1)+'</td><td><b>'+c.item+'</b>'+(c.obs?'<div style="font-size:11px;color:#64748b">'+c.obs+'</div>':'')+'</td><td style="background:'+cor+';font-weight:800;text-align:center">'+icone+' '+(c.status||'N/A')+'</td></tr>'});const qConf=checklist.filter((c:any)=>c.status==='Conforme').length;const qNao=checklist.filter((c:any)=>c.status==='Não Conforme').length;const fotos=item.fotos||(item.foto?[item.foto]:[]);const legendas=item.legendas||[];let fotosHtml='';if(!fotos.length)fotosHtml='Sem fotos na visita';else fotosHtml=fotos.map((f:string,i:number)=>'<div style="border:1px solid #e2e8f0;border-radius:12px;padding:8px;width:220px"><img src="'+f+'" style="width:100%;height:150px;object-fit:cover;border-radius:8px" /><div style="font-size:11px;margin-top:6px"><b>Foto '+(i+1)+' - '+dataVisita+'</b><div>'+(legendas[i]||item.local||'Local inspecionado')+'</div></div></div>').join('');const conclusao=item.conclusao||(qNao===0?'Local em conformidade - Seguro para operação':qNao<=2?'Local com restrições - Corrigir não conformidades':'Local com restrições graves - Interditar área até correção');const html='<html><head><meta charset="utf-8"><title>Laudo de Inspeção</title><style>body{font-family:Arial;padding:28px;max-width:1000px;margin:0 auto;font-size:13px;line-height:1.6}table{width:100%;border-collapse:collapse}th{background:#0f172a;color:#fff;padding:10px;text-align:left}td{padding:10px;border-bottom:1px solid #e2e8f0}.card{border:1px solid #e2e8f0;border-radius:12px;padding:14px;background:#f8fafc}h2{background:#0f172a;color:#fff;padding:8px 12px;border-radius:8px;font-size:14px}.btnprint{text-align:center;margin:16px}@media print{.btnprint{display:none}}</style></head><body>'+'<h1 style="text-align:center">📋 LAUDO / RELATÓRIO DE INSPEÇÃO DE SEGURANÇA DO TRABALHO</h1><p style="text-align:center;color:#64748b">PREVIX SST • Emitido: '+hoje+'</p>'+'<h2>1. IDENTIFICAÇÃO DA EMPRESA E DO LOCAL</h2><div class="card"><p><b>Razão Social:</b> '+empNome+'</p><p><b>CNPJ:</b> '+cnpjFinal+'</p><p><b>Endereço:</b> '+enderecoFinal+'</p><p><b>Setor / Área Inspecionada:</b> '+(item.setorArea||item.local||'-')+'</p><p><b>Local:</b> '+(item.local||'-')+' • <b>Data da Visita:</b> '+dataVisita+' • <b>Acompanhante:</b> '+(item.responsavel||'-')+'</p></div>'+'<h2>2. PROFISSIONAL RESPONSÁVEL</h2><div class="card"><p><b>Nome:</b> '+tecnico.nome+'</p><p><b>Formação:</b> '+(tecnico.formacao||tecnico.funcao||'-')+'</p><p><b>Registro:</b> CREA: '+(tecnico.crea||'-')+' • CRM: '+(tecnico.crm||'-')+'</p><p><b>ART:</b> '+(tecnico.art||item.art||'A preencher')+'</p></div>'+'<h2>3. INTRODUÇÃO E OBJETIVO</h2><p><b>Motivo:</b> '+motivo+'</p><p><b>Objetivo:</b> '+(item.objetivo||'Verificar as condições de segurança e saúde no trabalho, identificar conformidades e não conformidades e recomendar ações corretivas conforme NRs aplicáveis.')+'</p><p><b>Título:</b> '+(item.titulo||'-')+' • <b>Tipo:</b> '+tipo+'</p>'+'<h2>4. METODOLOGIA UTILIZADA</h2><p><b>Como foi feita:</b> '+metodologias+'</p><p>Visita in loco, checklist, registro fotográfico datado, consulta às NRs e entrevista quando necessário.</p>'+'<h2>5. DESCRIÇÃO DOS ACHADOS (DIAGNÓSTICO)</h2><p><b>Resumo:</b> ✅ Conforme: '+qConf+' • ❌ Não Conforme: '+qNao+'</p><p>'+(item.observacoes||item.descricao||'Sem observações.')+'</p><table><thead><tr><th>#</th><th>Item Verificado</th><th>Resultado</th></tr></thead><tbody>'+linhasCheck+'</tbody></table><p><b>Não Conformidades:</b> '+(item.naoConformidades||(qNao===0?'Nenhuma.':'Ver itens Não Conforme acima.'))+'</p>'+'<h2>6. REGISTRO FOTOGRÁFICO</h2><p style="font-size:12px;color:#64748b">Fotos datadas e legendadas.</p><div style="display:flex;gap:12px;flex-wrap:wrap">'+fotosHtml+'</div>'+'<h2>7. PLANO DE AÇÃO / RECOMENDAÇÕES</h2><p><b>🚨 Ações Imediatas (até 7 dias):</b> '+(item.acaoImediata||'Interditar / isolar área com risco grave, desligar equipamento com defeito, fornecer EPI correto.')+'</p><p><b>📅 Longo Prazo (30-90 dias):</b> '+(item.acaoLongoPrazo||item.planoAcao||'Corrigir sinalização, revisar PGR, treinamentos, manutenção preventiva.')+'</p>'+'<h2>8. CONCLUSÃO E ASSINATURA</h2><p><b>Parecer Final:</b> '+conclusao+'</p><p>'+(item.parecer||(qNao===0?'Local seguro para operação.':'Local com restrições. Corrigir ações imediatas antes de operar sem restrições.'))+'</p>'+'<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:50px;text-align:center"><div><div style="border-top:1px solid #000;width:90%;margin:0 auto"></div><b>'+tecnico.nome+'</b><div>'+(tecnico.formacao||'')+'</div><div>CREA: '+(tecnico.crea||'-')+' • CRM: '+(tecnico.crm||'-')+' • ART: '+(tecnico.art||'-')+'</div></div><div><div style="border-top:1px solid #000;width:90%;margin:0 auto"></div><b>'+(item.responsavel||empNome)+'</b><div>Acompanhante / Empresa - '+dataVisita+'</div></div></div>'+'<div class="btnprint"><button onclick="window.print()" style="background:#0d9488;color:#fff;border:none;padding:14px 28px;border-radius:20px;font-weight:800">Imprimir / Salvar PDF do Laudo</button></div></body></html>';const w=window.open('','_blank');if(w){w.document.write(html);w.document.close()}}
function gerarTermo(entrega:any){const func=(dados.funcionarios||[]).find((f:any)=>f.nome===entrega.funcionario)||{};const empNome=entrega.empresa||func.empresa||usuario?.empresa||'PREVIX SST';const dataFmt=entrega.data_entrega?entrega.data_entrega.split('-').reverse().join('/'):new Date().toLocaleDateString('pt-BR');const formas=[];if(entrega.pinVerificado)formas.push('PIN ✅');if(entrega.biometria)formas.push('Digital ✅');if(entrega.assinaturaImg)formas.push('Assinatura ✅');const html='<html><head><meta charset="utf-8"><title>Termo</title><style>body{font-family:Arial;padding:28px;max-width:820px;margin:0 auto}</style></head><body><h1 style="text-align:center">Termo de Entrega de EPI - NR-06</h1><p><b>Empresa:</b> '+empNome+'</p><p><b>Funcionário:</b> '+(entrega.funcionario||'-')+' - CPF: '+(func.cpf||'-')+'</p><p><b>EPI:</b> '+iconeEpi(entrega.nome)+' '+(entrega.nome||'-')+' - CA: '+(entrega.ca||'-')+' - Data: '+dataFmt+'</p><p><b>Confirmação:</b> '+(formas.length?formas.join(' • '):'Verbal')+'</p>'+(entrega.assinaturaImg?'<p style="text-align:center"><img src="'+entrega.assinaturaImg+'" style="max-width:300px;border:1px solid #ccc" /></p>':'')+'<div style="text-align:center;margin-top:20px"><button onclick="window.print()">Imprimir / PDF</button></div></body></html>';const w=window.open('','_blank');if(w){w.document.write(html);w.document.close()}}
function fazerLogin(){setErroLogin('');const login=loginForm.login.trim().toLowerCase();const senha=loginForm.senha.trim();if(login===ADMIN.login&&senha===ADMIN.senha){setUsuario(ADMIN);localStorage.setItem('previx_session',JSON.stringify(ADMIN));setAba('inicio');return}if(login==='admin'&&senha==='admin'){setUsuario(ADMIN);localStorage.setItem('previx_session',JSON.stringify(ADMIN));setAba('inicio');return}const emp=(dados.empresas||[]).find((e:any)=>(e.login||'').toLowerCase()===login&&(e.senha||'')===senha);if(emp){const u={login:emp.login,nome:emp.responsavel||emp.nome,tipo:'empresa',empresa:emp.nome};setUsuario(u);localStorage.setItem('previx_session',JSON.stringify(u));setAba('inicio');return}setErroLogin('Login ou senha incorretos!')}
function sair(){setUsuario(null);localStorage.removeItem('previx_session');setLoginForm({login:'',senha:''});setAba('inicio')}
function abrirNovo(){setEditando(null);setForm({});if(aba==='empresas')setForm({senha:gerarSenha(),status:'Ativa'});if(aba==='funcionarios')setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',pin:gerarPIN(),setor:'Vendas'});if(aba==='epis'){setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',data_entrega:new Date().toISOString().split('T')[0],quantidade:1,tipo:'',modelo:''});setPinDigitado('');setPinVerificado(false);setAssinaturaFeita(false);setBioStatus('aguardando');setBioMsg('');setTimeout(()=>{const c=canvasRef.current;if(c){const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height)}},100)}if(aba==='exames')setForm({data:diaSel,tipo:'Periódico',resultado:'Aguardando',clinica:clinicaSel});if(aba==='documentos')setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',pasta:pastaAtual==='Todas'?'PGR':pastaAtual,vencimento:new Date().toISOString().split('T')[0]});if(aba==='inspecoes'){const tipo0='Visita Técnica Geral';const itens0=TIPOS_INSPECAO.find(t=>t.id===tipo0)?.itens||[];setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',status:'Realizada',data:new Date().toISOString().split('T')[0],tipoInspecao:tipo0,tipo:tipo0,motivo:'Rotina Periódica',metodologias:['Visita in loco','Checklist','Fotografias','Consulta às NRs'],checklist:itens0.map(it=>({item:it,status:'Conforme',obs:''})),observacoes:'',naoConformidades:'',acaoImediata:'',acaoLongoPrazo:'',planoAcao:'',conclusao:'',parecer:'',objetivo:'',fotos:[],legendas:[],setorArea:'Vendas',cnpjEmpresa:'',enderecoEmpresa:'',art:tecnico.art||''})}if(aba==='riscos')setForm({ghe:'Vendas',tipo:'Físico'});if(aba==='financeiro')setForm({status:'Pendente',vencimento:new Date().toISOString().split('T')[0]});if(aba==='clinicas')setForm({status:'Ativa',convenio:'Vigente',cnpj:''});if(aba==='extintores')setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',tipo:'PQS 6kg',vencimento:new Date().toISOString().split('T')[0]});setModal(true)}
function abrirEditar(item:any){setEditando(item);setForm({...item});setPinDigitado('');setPinVerificado(!!item.pinVerificado);setAssinaturaFeita(!!item.assinaturaImg);setBioStatus(item.biometria?'ok':'aguardando');setBioMsg(item.biometria||'');setModal(true)}
function verificarPIN(){const func=(dados.funcionarios||[]).find((f:any)=>f.nome===form.funcionario)||(dados.funcionarios||[]).find((f:any)=>(f.cpf||'')===form.funcionario);if(!func){alert('Primeiro escolhe o funcionário!');return}if(pinDigitado===String(func.pin)){setPinVerificado(true);alert('✅ PIN correto! Já pode salvar só com o PIN.')}else{setPinVerificado(false);alert('❌ PIN incorreto. Usa digital / assinatura.')}}
async function coletarBiometria(){if(!form.funcionario){alert('Primeiro escolhe o funcionário!');return}setBioStatus('lendo');setBioMsg('Encosta o dedo... lendo digital...');try{if(typeof window!=='undefined'&&(window as any).PublicKeyCredential){const challenge=new Uint8Array(32);crypto.getRandomValues(challenge);const cred:any=await Promise.race([(navigator as any).credentials.create({publicKey:{challenge,rp:{name:'PREVIX SST'},user:{id:new Uint8Array(16),name:form.funcionario,displayName:form.funcionario},pubKeyCredParams:[{alg:-7,type:'public-key'}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required'},timeout:30000}}),new Promise((_,rej)=>setTimeout(()=>rej(new Error('timeout')),30000))]);if(cred){setBioStatus('ok');setBioMsg('Biometria confirmada - '+new Date().toLocaleString('pt-BR'));return}}}catch(e){}setTimeout(()=>{setBioStatus('ok');setBioMsg('Digital coletada - Biometria OK - '+new Date().toLocaleString('pt-BR'))},1800)}
function limparAssinatura(){const c=canvasRef.current;if(c){const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height)}setAssinaturaFeita(false)}
function posCanvas(e:any){const c=canvasRef.current;const r=c.getBoundingClientRect();const t=e.touches?.[0]||e;return{x:t.clientX-r.left,y:t.clientY-r.top}}
function subirFotoExtintor(e:any){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>setForm({...form,foto:reader.result});reader.readAsDataURL(file)}
function subirDoc(e:any){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>setForm({...form,arquivo:reader.result,nomeArquivo:file.name,tipoArquivo:file.type,titulo:form.titulo||file.name.replace(/\.[^/.]+$/,'')});reader.readAsDataURL(file)}
function subirFotoInspecao(e:any){const files=Array.from(e.target.files||[]);files.forEach((file:any)=>{const reader=new FileReader();reader.onload=()=>setForm((prev:any)=>({...prev,fotos:[...(prev.fotos||[]),reader.result],legendas:[...(prev.legendas||[]),'']}));reader.readAsDataURL(file)})}
function baixarDoc(item:any){if(!item.arquivo){alert('Sem arquivo.');return}const a=document.createElement('a');a.href=item.arquivo;a.download=item.nomeArquivo||(item.titulo+'.pdf');a.click()}
function salvar(){if(!aba||aba==='inicio')return;const f={...form};if(aba==='funcionarios'){if(!f.pin)f.pin=gerarPIN();if(!f.nome){alert('Coloca o nome!');return}if(!f.setor)f.setor='Vendas'}if(aba==='exames'){if(!f.nome){alert('Escolhe o funcionário!');return}f.data=limparData(f.data)||new Date().toISOString().split('T')[0];f.funcionario=f.nome;if(!f.clinica)f.clinica=clinicaSel}if(aba==='epis'){if(!f.nome){alert('Escolhe o EPI!');return}if(!f.funcionario){alert('Digita nome OU CPF!');return}if(!podeSalvarEpi){alert('⚠️ Escolhe pelo menos 1 forma: PIN OU Digital OU Assinatura');return}const c=canvasRef.current;f.assinaturaImg=assinaturaFeita&&c?c.toDataURL():f.assinaturaImg||'';f.pinVerificado=pinVerificado;f.confDigital=bioStatus==='ok';f.biometria=bioStatus==='ok'?(bioMsg||'Biometria OK'):'';f.quantidade=f.quantidade||1;f.formaConfirmacao=(pinVerificado?'PIN ':'')+(bioStatus==='ok'?'Digital ':'')+(assinaturaFeita?'Assinatura':'')}if(aba==='inspecoes'){if(!f.titulo){alert('Coloca o título da visita!');return}if(!f.tipoInspecao)f.tipoInspecao='Visita Técnica Geral';f.tipo=f.tipoInspecao;if(f.cnpjEmpresa)f.cnpjEmpresa=mascaraCNPJ(f.cnpjEmpresa);const nc=(f.checklist||[]).filter((c:any)=>c.status==='Não Conforme').length;if(!f.status||f.status==='Pendente')f.status=nc>0?'Com Não Conformidade':'Conforme'}if(aba==='extintores'){if(!f.localizacao&&!f.nome){alert('Coloca a localização!');return}if(!f.vencimento){alert('Coloca o vencimento!');return}f.nome=f.localizacao||f.nome||'Extintor'}if(aba==='documentos'){if(!f.titulo){alert('Coloca o título ou sobe o arquivo!');return}if(!f.pasta)f.pasta='PGR';f.tipo=f.pasta}if(aba==='clinicas'){if(!f.nome){alert('Coloca o nome da clínica!');return}if(f.cnpj)f.cnpj=mascaraCNPJ(f.cnpj)}if(aba==='empresas'){if(!f.login&&f.nome)f.login=f.nome.toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,12);if(!f.senha)f.senha=gerarSenha();if(f.cnpj)f.cnpj=mascaraCNPJ(f.cnpj)}if(aba==='riscos'&&!f.nome){alert('Coloca o risco!');return}if(aba==='financeiro'&&!f.descricao){alert('Descrição!');return}if(usuario?.tipo==='empresa')f.empresa=usuario.empresa;const lista=[...(dados[aba]||[])];if(editando){const id=editando.id||editando._id;const idx=lista.findIndex((x:any)=>(x.id||x._id)===id);if(idx>=0)lista[idx]={...lista[idx],...f};const nd={...dados,[aba]:lista};setDados(nd);salvarNav(nd)}else{const novo={...f,id:Date.now().toString(),status:f.status||'Ativa'};lista.push(novo);const nd={...dados,[aba]:lista};setDados(nd);salvarNav(nd);if(aba==='funcionarios')alert('✅ '+novo.nome+' • PIN: '+novo.pin);if(aba==='epis')alert('✅ Entrega confirmada com: '+(novo.formaConfirmacao||'1 forma'))}setModal(false);setForm({});setEditando(null)}
function excluir(item:any){if(!confirm('Excluir '+(item.nome||item.titulo||item.descricao||'registro')+'?'))return;const id=item.id||item._id;const nl=(dados[aba]||[]).filter((x:any)=>(x.id||x._id)!==id);const nd={...dados,[aba]:nl};setDados(nd);salvarNav(nd)}
function confirmarAgendamento(){if(!funcAgend){alert('Escolhe o funcionário!');return}if(tiposSel.length===0){alert('Marca 1 tipo!');return}const novos=tiposSel.map(t=>({id:Date.now().toString()+Math.random().toString().slice(2,6),nome:funcAgend,funcionario:funcAgend,tipo:t,data:diaSel,resultado:'Aguardando',clinica:clinicaSel,empresa:usuario?.empresa||'',status:'Agendado'}));const nd={...dados,exames:[...(dados.exames||[]),...novos]};setDados(nd);salvarNav(nd);alert('✅ Agendado! '+funcAgend+' • '+clinicaSel+' • '+fmtData(diaSel));setTiposSel([]);setFuncAgend('')}
function mudarMes(delta:number){const [y,m,d]=diaSel.split('-').map(Number);const dt=new Date(y,m-1+delta,1);setDiaSel(dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-01')}
