const funcSelEpi=(dados.funcionarios||[]).find((f:any)=>f.nome===form.funcionario)||(dados.funcionarios||[]).find((f:any)=>(f.cpf||'')===form.funcionario)||null
const textoEpi=String(form.nome||'').trim().toLowerCase()
