<div style={{border:'2px dashed #0d9488',borderRadius:16,padding:14}}><b>✍️ Assinatura - Opcional</b><p style={{fontSize:12,color:'#64748b'}}>Se não quiser PIN nem digital, só assinar aqui já salva.</p><canvas ref={canvasRef} width={460} height={140} style={{width:'100%',height:140,background:'white',borderRadius:12,border:'1px solid #e2e8f0',touchAction:'none'}} onMouseDown={(e:any)=>{desenhando.current=true;const c=canvasRef.current;const ctx=c.getContext('2d');const p=posCanvas(e);ctx.beginPath();ctx.moveTo(p.x,p.y)}} onMouseMove={(e:any)=>{if(!desenhando.current)return;const c=canvasRef.current;const ctx=c.getContext('2d');const p=posCanvas(e);ctx.lineTo(p.x,p.y);ctx.strokeStyle='#0f172a';ctx.lineWidth=2;ctx.stroke();setAssinaturaFeita(true)}} onMouseUp={()=>desenhando.current=false} onMouseLeave={()=>desenhando.current=false} onTouchStart={(e:any)=>{desenhando.current=true;const c=canvasRef.current;const ctx=c.getContext('2d');const p=posCanvas(e);ctx.beginPath();ctx.moveTo(p.x,p.y)}} onTouchMove={(e:any)=>{if(!desenhando.current)return;e.preventDefault();const c=canvasRef.current;const ctx=c.getContext('2d');const p=posCanvas(e);ctx.lineTo(p.x,p.y);ctx.strokeStyle='#0f172a';ctx.lineWidth=2;ctx.stroke();setAssinaturaFeita(true)}} onTouchEnd={()=>desenhando.current=false} /><div style={{display:'flex',gap:8,marginTop:8}}><button type="button" onClick={limparAssinatura} style={{...btn,background:'#fee2e2'}}>Limpar assinatura</button>{assinaturaFeita?<span style={{color:'#15803d',fontWeight:800,fontSize:13}}>✅ Assinatura pronta!</span>:null}</div></div>
